import{_ as e,o as i,c as r,a2 as o}from"./chunks/framework.DPTp4bo7.js";const h=JSON.parse('{"title":"Input / Output / Merge Priority Theory","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/input-output-merge-priority-theory"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/input-output-merge-priority-theory"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/input-output-merge-priority-theory"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/input-output-merge-priority-theory"}]]},"headers":[],"relativePath":"input-output-merge-priority-theory.md","filePath":"logistics/src/page-AA41FJVehHzDTC97GcFV5F.md"}'),n={name:"input-output-merge-priority-theory.md"};function s(a,t,p,l,u,c){return i(),r("div",null,[...t[0]||(t[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="优先输入-输出-汇入理论" aria-hidden="true"></span><h1 id="input-output-merge-priority-theory" tabindex="-1">Input / Output / Merge Priority Theory <a class="header-anchor" href="#input-output-merge-priority-theory" aria-label="Permalink to &quot;Input / Output / Merge Priority Theory&quot;">​</a></h1><blockquote><p>Source page ID: <code>AA41FJVehHzDTC97GcFV5F</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AA41FJVehHzDTC97GcFV5F" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>This page mainly helps readers unfamiliar with basic input/output priorities who find <a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a> difficult to read directly.</p><p><span id="source-block-LStqO3ihrJjZA2Uyti9bzr"></span></p><span class="logistics-source-anchor" id="优先输出-协议箱-汇流器-多口暗管出口-汇流器" aria-hidden="true"></span><h2 id="output-priority-protocol-stash–converger-conduit-outlet-manifold–converger" tabindex="-1">Output Priority: Protocol Stash–Converger / Conduit Outlet Manifold–Converger <a class="header-anchor" href="#output-priority-protocol-stash–converger-conduit-outlet-manifold–converger" aria-label="Permalink to &quot;Output Priority: Protocol Stash–Converger / Conduit Outlet Manifold–Converger&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-158b774bfb7274dc.q90-a0e442d04c7e3c73.webp" alt="Input / Output / Merge Priority Theory"></p><p>In brief, placing a Protocol Stash / Conduit Outlet Manifold flush against a converger creates output priority. Count the belts/pipes and logistics components on both routes—their damping. The route with fewer outputs first; the one with more outputs second.</p><p><span class="mark-grey">For solids, unlike fluids/gases, a multi-output machine such as a Packaging Unit or Shredding Unit can directly replace the Stash: placing a converger flush against its output creates output priority.</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c5624772107f24fe.gif" alt="Input / Output / Merge Priority Theory"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fe0d488ade871fd6.gif" alt="Input / Output / Merge Priority Theory"></p><p>For more complex cases: <a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a>.</p><p><span id="source-block-YaKEdAbnDnMx5Vv6e3oH6j"></span></p><span class="logistics-source-anchor" id="优先汇入-分流器-汇流器" aria-hidden="true"></span><h2 id="merge-priority-splitter–converger" tabindex="-1">Merge Priority: Splitter–Converger <a class="header-anchor" href="#merge-priority-splitter–converger" aria-label="Permalink to &quot;Merge Priority: Splitter–Converger&quot;">​</a></h2><p>If a splitter output is flush against a converger input, the converger gains merge priority: the upstream component placed first has priority. If that first component is not a splitter, it services later non-splitter components round-robin.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-82eba631c9f66e78.gif" alt="Input / Output / Merge Priority Theory"></p><p><span class="mark-grey">More precisely: among splitters, earlier-placed ones input first. Pipes, Fluid/Gas Tanks, Conduit Outlets and convergers share a priority determined by the first placed among them. Between splitters and that group, the earlier-placed side inputs first. Note that all pipe-type components share priority: connect pipe A, then splitter B, then pipe C to one converger, and A=C&gt;B.</span></p><p>Relations involving machines, splitters and pipes are not fully understood, chiefly because Reactor Crucibles are puzzling. Follow actual observed behavior.</p><p>For more complex cases: <a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a>.</p><p><span id="source-block-SJwMhKtD8ELVC0QucYr9nJ"></span></p><span class="logistics-source-anchor" id="通过正常轮询达成的输出-输入优先" aria-hidden="true"></span><h2 id="output-input-priority-through-normal-round-robin-servicing" tabindex="-1">Output / Input Priority through Normal Round-Robin Servicing <a class="header-anchor" href="#output-input-priority-through-normal-round-robin-servicing" aria-label="Permalink to &quot;Output / Input Priority through Normal Round-Robin Servicing&quot;">​</a></h2><p>Output priority: Conduit Outlet Manifold A supplies 120/min Xiragen. Its ports connect to Conduit Inlets B consuming 30/min and C consuming 120/min. B&#39;s demand is satisfied first. Strictly, if B/C&#39;s consumption is below half of A&#39;s flow, supply is guaranteed. The factor 1/2 arises because when both ports are unblocked the manifold outputs round-robin, equally over sufficiently long time. This is output priority in a broad sense.</p><p>Input priority: Conduit Inlet Manifold A consumes 120/min Xiragen. Its ports connect to Conduit Outlets B supplying 30/min and C supplying 120/min. B&#39;s output is consumed first. Strictly, if B/C&#39;s input is below half of A&#39;s flow, all of it is consumed. The factor 1/2 arises because when both ports are blocked the manifold inputs round-robin, equally over sufficiently long time. This is input priority in a broad sense. [The source calls B/C “Conduit Inlets” in this latter strict statement.]</p><p>For a more systematic explanation, I cite kokobird&#39;s <a href="/endfield-skydoc/2-5-is-a-stash-not-just-a-special-splitter">2.5 Is a Stash Not Just a Special Splitter? (Core Content ⭐)</a>.</p><p><span id="source-block-cSE6qgeFTPC10fGIVcuoTG"></span></p><span class="logistics-source-anchor" id="四卡一-迟滞输出-造成的输入优先级损坏" aria-hidden="true"></span><h2 id="input-priority-broken-by-the-4-1-stall-output-lag" tabindex="-1">Input Priority Broken by the “4, 1” Stall (Output Lag) <a class="header-anchor" href="#input-priority-broken-by-the-4-1-stall-output-lag" aria-label="Permalink to &quot;Input Priority Broken by the “4, 1” Stall (Output Lag)&quot;">​</a></h2><p>A splitter&#39;s “4, 1” stall may degrade priority into incomplete priority. If priority breaks and, with upstream blocked, two fluid units enter from the priority side for every one from the secondary side—instead of normal one-for-you, one-for-me round-robin—the stall is likely occurring. There are two simple repairs, whose sufficiency is still being verified:</p><p>Details: <a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a>.</p></div>',1)])])}const g=e(n,[["render",s]]);export{h as __pageData,g as default};
